\begin{tikzpicture}[x=1.35cm,y=1.2cm,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{curveBlue}{HTML}{268CFF}
\path[use as bounding box] (-0.5,-2.55) rectangle (4.45,2.65);
\draw[black,line width=0.5pt,->] (-0.04,0)--(4.15,0) node[right] {$x$};
\draw[black,line width=0.5pt,<->] (0,-2.2)--(0,2.2) node[above] {$y$};
\foreach \t in {1,...,12}{\draw[black,line width=0.4pt] ({\t/3},-0.04)--({\t/3},0.04);}
\foreach \t/\lab in {1/{\frac{\pi}{2}},2/{\pi},3/{\frac{3\pi}{2}},4/{2\pi}}{\node[below,font=\fontsize{8.5}{10}\selectfont] at (\t,-0.06) {\special{dvisvgm:raw <g data-graph-text="tick">}$\lab$\special{dvisvgm:raw </g>}};}
\foreach \v in {-2,-1,1,2}{\draw[black,line width=0.4pt] (-0.04,\v)--(0.04,\v);\node[left,font=\fontsize{8.5}{10}\selectfont] at (-0.05,\v) {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};}
\pgfmathsetmacro{\h}{atan(2.15)/180}
\draw[curveBlue,line width=0.8pt,->,domain=0:\h,samples=45] plot (\x,{-tan(180*\x)});
\foreach \n in {1,2,3}{\draw[curveBlue,line width=0.8pt,<->,domain={\n-\h}:{\n+\h},samples=81] plot (\x,{-tan(180*\x)});}
\draw[curveBlue,line width=0.8pt,<-,domain={4-\h}:4,samples=45] plot (\x,{-tan(180*\x)});
\end{tikzpicture}

